INSERT INTO proposals VALUES(6,'Arthur Ulfeldt','arthur@ulfeldt.com','Nixos, Guix, and declarative system configuration, ?Is this worth it? ','Managing a computer in code is really cool, in practice it&#39;s a lot of work. let&#39;s share our experiences and talk about how much effort this is worth.','','2025-11-08 03:43:10',NULL,0,'9257855529');
