INSERT INTO proposals VALUES(8,'Bob Somers','bob@bobsomers.com','Grassroots Political Activism - What&#39;s effective and how to to get involved in 2025','What has been effective so far this year, what hasn&#39;t. How you can get involved in local groups or start one of your own. The point here is not to discuss politics, but rather strategies and tactics for effective grassroots activism, whatever your cause.','','2025-11-08 03:44:22.000000','choke download BOF',0,'6616191457');
INSERT INTO proposals VALUES(9,'Getting More Hack Done &quot;GTD&quot; for haks','arthur@ulfeldt.com','Getting More Hack Done:','We all have more projects and ideas than are actually getting hacked on. Let&#39;s present our personal methods for TODO&#39;s, reducing stress, and getting the projects we care about done first','','2025-11-08 03:44:40',NULL,0,'9257855529');
