INSERT INTO proposals VALUES(12,'Katy (Bluehat)','','Mask fit testing','A best effort qualitative mask fit test with saccharine solution. You need to not eat or drink for 20 minutes before your test. Many people prefer a fresh mask or filters and possibly a shower after their fit test.','Outside','2025-11-08 03:45:36',NULL,0,'360-480-0355');
