INSERT INTO proposals VALUES(14,'David A Smith','davidasmith@gmail.com','Decentralized Computation/Communication/Collaboration','Safe, secure, fast decentralized computation, communication, collaboration.','','2025-11-08 03:47:20.000000','sharchive flaky netsplit',0,'9192444448');
INSERT INTO proposals VALUES(15,'Almus','almus@g33k.bar','Pen and Paper Puzzles','Hackers love a good puzzle, from the tidy logic of Sudoku to the viral &quot;daily&quot; hits like Wordle, to the custom cipher hunts and invite-only riddles that pop up at hacker parties and conferences. This is for anyone who likes decoding, designing, or just admiring puzzles that stretch the brain. We’ll trade favorites, talk through how different puzzle types hook us, and look at how original, event-specific challenges are built and solved. If there’s interest, we’ll walk through a new cipher puzzle that Seric and I created just for Hackers and unpack how it works from construction to solution. Bring a notebook. Curiosity required; expertise optional.','Projector for paper puzzles would be &quot;nice to have&quot; for sharing but not necessary.','2025-11-08 03:47:48',NULL,0,'');
