INSERT INTO mails VALUES(1,'Pyr0303@gmail.com','The BoF ''Digital Radio (p25/nxdn/and other crazy things)'' has reached enough interest to be scheduled',replace('--boundary-string\nContent-Type: text/plain; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\nThe BoF "Digital Radio (p25/nxdn/and other crazy things)" which you proposed, has now received interest from 8 people.\n\nThe following attendees have expressed interest in this session:\n - Bob Somers\n - Ben Reiter\n - Shaunak De\n - Mouse\n - Scott manley\n - Kees Cook\n - Alvaro\n - Jonathan Tomek\n\nPlease log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.\n\nYou can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words:\ncretinous avatar exec\n\nThank you,\n - BoF Scheduling System\n\n\n--boundary-string\nContent-Type: text/html; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\n<p>The BoF "Digital Radio (p25/nxdn/and other crazy things)" which you proposed, has now received interest from 8 people.</p>\n\n<p>The following attendees have expressed interest in this session:</p>\n<ul>\n<li>Bob Somers</li>\n<li>Ben Reiter</li>\n<li>Shaunak De</li>\n<li>Mouse</li>\n<li>Scott manley</li>\n<li>Kees Cook</li>\n<li>Alvaro</li>\n<li>Jonathan Tomek</li>\n</ul>\n\n<p>Please log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.</p>\n\n<p>You can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words: cretinous avatar exec. Alternatively, click the following link to <a href="http://bof.hackersconference.org/selfschedule?token=cretinous+avatar+exec">self-schedule</a> if you are on the wifi.</p>\n\n<p>Thanks!</p>\n<p> - BoF Team</p>\n\n--boundary-string--','\n',char(10)),'READY','2025-11-08 04:14:15');
