INSERT INTO mails VALUES(15,'davidasmith@gmail.com','The BoF ''Decentralized Computation/Communication/Collaboration'' has reached enough interest to be scheduled',replace('--boundary-string\nContent-Type: text/plain; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\nThe BoF "Decentralized Computation/Communication/Collaboration" which you proposed, has now received interest from 8 people.\n\nThe following attendees have expressed interest in this session:\n - David A Smith\n - Alex Komoroske\n - Aran Lunzer\n - Marko\n - Craig Latta\n - Arthur Ulfeldt\n - Kevin Wallace\n - Mike Bentley\n\nPlease log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.\n\nYou can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words:\nsharchive flaky netsplit\n\nThank you,\n - BoF Scheduling System\n\n\n--boundary-string\nContent-Type: text/html; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\n<p>The BoF "Decentralized Computation/Communication/Collaboration" which you proposed, has now received interest from 8 people.</p>\n\n<p>The following attendees have expressed interest in this session:</p>\n<ul>\n<li>David A Smith</li>\n<li>Alex Komoroske</li>\n<li>Aran Lunzer</li>\n<li>Marko</li>\n<li>Craig Latta</li>\n<li>Arthur Ulfeldt</li>\n<li>Kevin Wallace</li>\n<li>Mike Bentley</li>\n</ul>\n\n<p>Please log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.</p>\n\n<p>You can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words: sharchive flaky netsplit. Alternatively, click the following link to <a href="http://bof.hackersconference.org/selfschedule?token=sharchive+flaky+netsplit">self-schedule</a> if you are on the wifi.</p>\n\n<p>Thanks!</p>\n<p> - BoF Team</p>\n\n--boundary-string--