INSERT INTO mails VALUES(30,'piotr@esden.net','The BoF ''Remote Debugger System'' has reached enough interest to be scheduled',replace('--boundary-string\nContent-Type: text/plain; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\nThe BoF "Remote Debugger System" which you proposed, has now received interest from 8 people.\n\nThe following attendees have expressed interest in this session:\n - barbie\n - Piotr Esden-Tempski\n - Joe\n - Alvaro\n - Ben H\n - Karl Koscher\n - Rob Savoye\n - Chuck mcmanis\n\nPlease log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.\n\nYou can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words:\ntrit source PEBKAC\n\nThank you,\n - BoF Scheduling System\n\n\n--boundary-string\nContent-Type: text/html; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\n<p>The BoF "Remote Debugger System" which you proposed, has now received interest from 8 people.</p>\n\n<p>The following attendees have expressed interest in this session:</p>\n<ul>\n<li>barbie</li>\n<li>Piotr Esden-Tempski</li>\n<li>Joe</li>\n<li>Alvaro</li>\n<li>Ben H</li>\n<li>Karl Koscher</li>\n<li>Rob Savoye</li>\n<li>Chuck mcmanis</li>\n</ul>\n\n<p>Please log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.</p>\n\n<p>You can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words: trit source PEBKAC. Alternatively, click the following link to <a href="http://bof.hackersconference.org/selfschedule?token=trit+source+PEBKAC">self-schedule</a> if you are on the wifi.</p>\n\n<p>Thanks!</p>\n<p> - BoF Team</p>\n\n--boundary-string--','\n',char(10)),'READY','2025-11-08 06:56:11');
