INSERT INTO mails VALUES(51,'piotr@esden.net','Your BoF ''Remote Debugger System'' has been scheduled!',replace('--boundary-string\nContent-Type: text/plain; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\nYour proposed BoF "Remote Debugger System" has been scheduled! This session will be taking place on Saturday at 11:00 in Lighthouse.\n\nThe following attendees have expressed interest in this session:\n - barbie\n - Piotr Esden-Tempski\n - Joe\n - Alvaro\n - Ben H\n - Karl Koscher\n - Rob Savoye\n - Chuck mcmanis\n\nTo add this to your calendar, use these links:\n- Google Calendar: https://www.google.com/calendar/render?action=TEMPLATE&text=Remote%20Debugger%20System&dates=20251108T110000/20251108T120000&ctz=America/Los_Angeles&location=Lighthouse\n- Office 365 Calendar: https://outlook.office.com/calendar/0/action/compose?rru=addevent&subject=Remote%20Debugger%20System&startdt=2025-11-08T19:00:00Z&enddt=2025-11-08T20:00:00Z&location=Lighthouse\n- iCal/ics: attached\n\nIf you have any questions or need something changed please reach out to bentley, the scheduler who processed this session.\n\nThanks!\n - BoF Team\n\n\n--boundary-string\nContent-Type: text/html; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\n<p>Your proposed BoF "Remote Debugger System" has been scheduled! This session will be taking place on Saturday at 11:00 in Lighthouse.</p>\n\n<p>The following attendees have expressed interest in this session:</p>\n<ul>\n<li>barbie</li>\n<li>Piotr Esden-Tempski</li>\n<li>Joe</li>\n<li>Alvaro</li>\n<li>Ben H</li>\n<li>Karl Koscher</li>\n<li>Rob Savoye</li>\n<li>Chuck mcmanis</li>\n</ul>\n\n<p>To add this to your calendar, use these links:\n<a href=''https://www.google.com/calendar/render?action=TEMPLATE&text=Remote%20Debugger%20System&dates=20251108T110000/20251108T120000&ctz=America/Los_Angeles&location=Lighthouse''>Google Calendar</a>, \n<a href=''https://outlook.office.com/calendar/0/action/compose?rru=addevent&subject=Remote%20Debugger%20System&startdt=2025-11-08T19:00:00Z&enddt=2025-11-08T20:00:00Z&location=Lighthouse''>Office 365</a>\n</p>\n\n<p>If you have any questions or need something changed please reach out to bentley, the scheduler who processed this session.</p>\n\n<p>Thanks!</p>\n<p> - BoF Team</p>\n\n\n--boundary-string\nContent-Type: text/calendar; charset="utf-8"; name="bof-27.ics"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: attachment; filename="bof-27.ics"\n\nBEGIN:VCALENDAR\nVERSION:2.0\nPRODID:-//AddToCalendar//RubyGem//EN\nBEGIN:VEVENT\nDTSTAMP:20251108T073817Z\nDTSTART:20251108T190000Z\nDTEND:20251108T200000Z\nSUMMARY:Remote Debugger System\nLOCATION:Lighthouse\nUID:-20251108T190000Z-Remote Debugger System\nEND:VEVENT\nEND:VCALENDAR\n--boundary-string--','\n',char(10)),'READY','2025-11-08 07:38:17');
