INSERT INTO mails VALUES(124,'arthur@ulfeldt.com','The BoF ''Meshtastic'' has reached enough interest to be scheduled',replace('--boundary-string\nContent-Type: text/plain; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\nThe BoF "Meshtastic" which you proposed, has now received interest from 8 people.\n\nThe following attendees have expressed interest in this session:\n - Kees Cook\n - Kees Cook\n - Jonathan Tomek\n - Pablo Breuer\n - Pyr0\n - Shaunak De\n - Morgan\n - Sean Silva\n\nPlease log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.\n\nYou can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words:\nwabbit hop glassfet\n\nThank you,\n - BoF Scheduling System\n\n\n--boundary-string\nContent-Type: text/html; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\n<p>The BoF "Meshtastic" which you proposed, has now received interest from 8 people.</p>\n\n<p>The following attendees have expressed interest in this session:</p>\n<ul>\n<li>Kees Cook</li>\n<li>Kees Cook</li>\n<li>Jonathan Tomek</li>\n<li>Pablo Breuer</li>\n<li>Pyr0</li>\n<li>Shaunak De</li>\n<li>Morgan</li>\n<li>Sean Silva</li>\n</ul>\n\n<p>Please log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.</p>\n\n<p>You can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words: wabbit hop glassfet. Alternatively, click the following link to <a href="http://bof.hackersconference.org/selfschedule?token=wabbit+hop+glassfet">self-schedule</a> if you are on the wifi.</p>\n\n<p>Thanks!</p>\n<p> - BoF Team</p>\n\n--boundary-string--','\n',char(10)),'READY','2025-11-08 18:11:14');
