INSERT INTO mails VALUES(133,'craig@netjam.org','The BoF ''reverse-engineering AI models'' has reached enough interest to be scheduled',replace('--boundary-string\nContent-Type: text/plain; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\nThe BoF "reverse-engineering AI models" which you proposed, has now received interest from 8 people.\n\nThe following attendees have expressed interest in this session:\n - Craig Latta\n - Aurora\n - Morgan\n - barbie\n - Ned konz\n - D&#39;oh! Stupid phone... That should be &quot;mechanistic interpretability&quot; --Craig\n - Marc Rogers\n - Stephen Williams\n\nPlease log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.\n\nYou can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words:\nretcon massage EOL\n\nThank you,\n - BoF Scheduling System\n\n\n--boundary-string\nContent-Type: text/html; charset="utf-8"\nContent-Transfer-Encoding: 7BIT\nContent-Disposition: inline\n\n<p>The BoF "reverse-engineering AI models" which you proposed, has now received interest from 8 people.</p>\n\n<p>The following attendees have expressed interest in this session:</p>\n<ul>\n<li>Craig Latta</li>\n<li>Aurora</li>\n<li>Morgan</li>\n<li>barbie</li>\n<li>Ned konz</li>\n<li>D&#39;oh! Stupid phone... That should be &quot;mechanistic interpretability&quot; --Craig</li>\n<li>Marc Rogers</li>\n<li>Stephen Williams</li>\n</ul>\n\n<p>Please log in and self-schedule this session. If you do not schedule it within 15 minutes, a scheduler will be notified to schedule it for you.</p>\n\n<p>You can do this by clicking the "Self-Schedule" tool in bof-o-matic, and entering the following words: retcon massage EOL. Alternatively, click the following link to <a href="http://bof.hackersconference.org/selfschedule?token=retcon+massage+EOL">self-schedule</a> if you are on the wifi.</p>\n\n<p>Thanks!</p>\n<p> - BoF Team</p>\n\n--boundary-string--','\n',char(10)),'READY','2025-11-08 19:38:52');
