PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE `schema_info` (`version` integer DEFAULT (0) NOT NULL);
CREATE TABLE `proposals` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `submitted_by` varchar(255) NOT NULL, `submitter_email` varchar(255) NOT NULL, `title` varchar(255) NOT NULL, `description` varchar(255) NOT NULL, `scheduler_notes` varchar(255), `submitted_at` timestamp DEFAULT (datetime(CURRENT_TIMESTAMP, 'localtime')), `scheduling_token` varchar(255), `sent_to_schedulers` boolean DEFAULT (0), `submitter_phone` varchar(255));
CREATE TABLE `interests` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `proposal_id` integer NOT NULL, `name` varchar(255) NOT NULL, `email` varchar(255), `submitted_at` timestamp DEFAULT (datetime(CURRENT_TIMESTAMP, 'localtime')), `phone` varchar(255));
CREATE TABLE `schedules` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `proposal_id` integer NOT NULL, `start_time` timestamp NOT NULL, `scheduled_at` timestamp DEFAULT (datetime(CURRENT_TIMESTAMP, 'localtime')), `scheduled_by` varchar(255), `room_id` integer, `reminders_sent` boolean DEFAULT (0));
CREATE TABLE `schedulers` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `username` varchar(255) NOT NULL, `pwhash` varchar(255) NOT NULL, `email` varchar(255), `phone` varchar(255));
CREATE TABLE `rooms` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `room_name` varchar(255) NOT NULL UNIQUE, `active` boolean DEFAULT (1) NOT NULL);
CREATE TABLE `mails` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `to_address` varchar(255) NOT NULL, `subject` varchar(255) NOT NULL, `body` varchar(255) NOT NULL, `status` varchar(5) DEFAULT ('READY') NOT NULL, `queued_at` timestamp DEFAULT (datetime(CURRENT_TIMESTAMP, 'localtime')));
CREATE TABLE `texts` (`id` integer NOT NULL PRIMARY KEY AUTOINCREMENT, `to_phone` varchar(255) NOT NULL, `body` varchar(255) NOT NULL, `status` varchar(5) DEFAULT ('READY') NOT NULL, `queued_at` timestamp DEFAULT (datetime(CURRENT_TIMESTAMP, 'localtime')));
DELETE FROM sqlite_sequence;
COMMIT;
